// Package safety detects destructive shell commands generated by the model.
//
// DESIGN, and why the obvious version does not work. This is a Go port of the
// whatisit checker (whatisit_pkg/whatisit/safety.py), whose module docstring
// records an adversarial audit. Read that before touching this file.
//
// The first version matched regexes against the raw command string, split on
// shell operators. An audit defeated it trivially and, worse, showed it was
// noisy at the same time:
//
//   - `rm -rf '/'` and `rm -rf "/"` passed clean, because a quote character
//     broke the delimiter the path pattern required. So did
//     `rm --recursive --force /`, because the flag pattern could not span the
//     second `-` of a long option.
//   - The "pipe remote content into a shell" rule was DEAD CODE: segments were
//     split on `|` before patterns ran, so the one rule needing a literal `|`
//     never matched.
//   - Meanwhile `rm -rf /home/user/project/build` was flagged, because `/home`
//     was matched as a PREFIX of a deeper path.
//
// A checker that is both evadable and noisy is worse than none. So this version
// does not pattern-match paths out of a raw string. It:
//  1. strips terminal control bytes (untrusted model output reaches a terminal),
//  2. tokenizes with a shlex equivalent, which removes quoting as a variable,
//  3. normalizes long options to their short forms,
//  4. extracts the actual TARGET arguments of destructive verbs, and
//  5. asks whether a target IS a critical path -- not whether one appears in it.
//
// Unresolvable targets ($VAR, command substitution) are treated as dangerous.
//
// This remains a denylist over a Turing-complete language. It is a seatbelt,
// not a sandbox: eval, base64 indirection, and aliasing defeat any static
// check. The default path never executes anything, which is the real protection.
//
// Note on regex: Go's regexp is RE2 and has no lookahead/lookbehind. The Python
// source leans on them heavily; every such construct was rewritten to an
// RE2-safe equivalent (explicit boundary groups that consume a delimiter, which
// is harmless because every rule here is a boolean search). The ported test
// suite in safety_test.go is the audit and proves the rewrites are faithful.
package safety

import (
	"fmt"
	"regexp"
	"strings"
)

// Level is the severity of a finding.
type Level int

const (
	// LevelSafe means nothing flagged.
	LevelSafe Level = iota
	// LevelCaution warns the user but the command may still be run.
	LevelCaution
	// LevelDanger must never be auto-run; the caller warns and prints anyway.
	LevelDanger
)

// Finding is one flagged reason. Reason is the user-facing line camne prints.
type Finding struct {
	Level  Level
	Reason string
}

// Worst returns the highest severity among findings (LevelSafe if none).
func Worst(fs []Finding) Level {
	w := LevelSafe
	for _, f := range fs {
		if f.Level > w {
			w = f.Level
		}
	}
	return w
}

// --- lookup tables (ports of the Python module-level sets) ------------------

// Paths that must be the TARGET ITSELF to count, never a prefix of a deeper one.
var criticalTargets = set(
	"/", "/bin", "/boot", "/dev", "/etc", "/home", "/lib", "/lib32", "/lib64",
	"/opt", "/proc", "/root", "/run", "/sbin", "/srv", "/sys", "/usr", "/var",
	"~", "$HOME", "${HOME}",
	"/var/log", "/var/lib", "/var/spool", "/usr/local", "/usr/bin", "/usr/lib",
	"/etc/ssh", "/etc/systemd",
)

// Individual files whose destruction breaks the system.
var criticalFiles = set(
	"/etc/passwd", "/etc/shadow", "/etc/group", "/etc/sudoers", "/etc/fstab",
	"/etc/hosts", "/etc/resolv.conf", "/boot/grub/grub.cfg",
)

// `/home` is critical and `/home/user/project/build` deliberately is not, but
// `/home/alice` is one whole user account -- exactly one component under /home.
var wholeHomeRe = regexp.MustCompile(`^/home/[^/]+/?$`)

var destructiveVerbs = set("rm", "rmdir", "shred", "unlink", "srm")
var moveVerbs = set("mv", "cp")
var permVerbs = set("chmod", "chown", "chgrp")
var shellRunners = set("sh", "bash", "zsh", "ksh", "dash", "fish", "ash")

// Tokens that prefix a real command without changing what it does.
var wrappers = set("sudo", "doas", "env", "nice", "ionice", "nohup", "command",
	"builtin", "exec", "time", "stdbuf", "setsid", "xargs", "busybox", "toybox")

// Per wrapper, the short options that consume a SEPARATE next token as value.
var wrapperValueOpts = map[string]map[string]bool{
	"sudo":   set("-u", "-g", "-h", "-p", "-r", "-t", "-C"),
	"doas":   set("-u"),
	"env":    set("-u", "-C", "-S"),
	"nice":   set("-n"),
	"ionice": set("-c", "-n", "-p", "-t"),
	"stdbuf": set("-i", "-o", "-e"),
	"xargs":  set("-I", "-i", "-n", "-P", "-d", "-s", "-a", "-L", "-l"),
}

var longToShort = map[string]string{
	"--recursive": "-r", "--force": "-f", "--dir": "-d",
	"--no-preserve-root": "-!", "--preserve-root": "",
}

func set(items ...string) map[string]bool {
	m := make(map[string]bool, len(items))
	for _, s := range items {
		m[s] = true
	}
	return m
}

// --- control-byte strip -----------------------------------------------------

// Model output is untrusted and lands in a terminal, where escape sequences can
// conceal or repaint what the user is about to approve.
var controlRe = regexp.MustCompile(
	"\x1b\\[[0-9;?]*[a-zA-Z]|\x1b\\][^\x07\x1b]*(?:\x07|\x1b\\\\)|[\x00-\x08\x0b-\x1f\x7f]")

func stripControl(s string) string { return controlRe.ReplaceAllString(s, "") }

// --- tokenizer (shlex equivalent) -------------------------------------------

var ansiCRe = regexp.MustCompile(`\$'((?:[^'\\]|\\.)*)'`)

var ansiEscapes = map[byte]string{
	'n': "\n", 't': "\t", 'r': "\r", '\\': "\\", '\'': "'",
	'0': "\x00", 'a': "\a", 'b': "\b", 'f': "\f", 'v': "\v",
}

// decodeAnsiC expands bash's $'...' quoting before the tokenizer sees it, then
// re-quotes so the rest of the pipeline reads the same string bash would.
func decodeAnsiC(segment string) string {
	return ansiCRe.ReplaceAllStringFunc(segment, func(m string) string {
		body := ansiCRe.FindStringSubmatch(m)[1]
		var out strings.Builder
		for i := 0; i < len(body); i++ {
			if body[i] == '\\' && i+1 < len(body) {
				if r, ok := ansiEscapes[body[i+1]]; ok {
					out.WriteString(r)
				} else {
					out.WriteByte(body[i+1])
				}
				i++
			} else {
				out.WriteByte(body[i])
			}
		}
		return shellQuote(out.String())
	})
}

func shellQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// tokenize splits a segment into shell words. Quoting is removed, so `'/'` and
// `/` are the same token. On unbalanced quotes it falls back to a whitespace
// split -- failing closed there would skip the check on exactly the malformed
// input most worth checking.
func tokenize(segment string) []string {
	segment = decodeAnsiC(segment)
	if toks, ok := shlexSplit(segment); ok {
		return toks
	}
	return strings.Fields(segment)
}

func shlexSplit(s string) ([]string, bool) {
	var toks []string
	var cur strings.Builder
	inTok := false
	for i := 0; i < len(s); {
		c := s[i]
		switch {
		case c == '\\':
			if i+1 >= len(s) {
				return nil, false // trailing backslash: no escaped character
			}
			cur.WriteByte(s[i+1])
			inTok = true
			i += 2
		case c == '\'':
			j := i + 1
			for j < len(s) && s[j] != '\'' {
				j++
			}
			if j >= len(s) {
				return nil, false // unbalanced
			}
			cur.WriteString(s[i+1 : j])
			inTok = true
			i = j + 1
		case c == '"':
			j := i + 1
			for j < len(s) && s[j] != '"' {
				if s[j] == '\\' && j+1 < len(s) {
					nc := s[j+1]
					if nc == '"' || nc == '\\' || nc == '$' || nc == '`' || nc == '\n' {
						cur.WriteByte(nc)
						j += 2
						continue
					}
				}
				cur.WriteByte(s[j])
				j++
			}
			if j >= len(s) {
				return nil, false // unbalanced
			}
			inTok = true
			i = j + 1
		case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v':
			if inTok {
				toks = append(toks, cur.String())
				cur.Reset()
				inTok = false
			}
			i++
		default:
			cur.WriteByte(c)
			inTok = true
			i++
		}
	}
	if inTok {
		toks = append(toks, cur.String())
	}
	return toks, true
}

// --- path handling ----------------------------------------------------------

// normPath canonicalizes a target for comparison, collapsing . and .. segments
// so `/usr/../` and `/../` both resolve to `/`.
func normPath(tok string) string {
	t := strings.TrimRight(tok, "/")
	if t == "" {
		t = "/"
	}
	absolute := strings.HasPrefix(t, "/")
	var parts []string
	for _, seg := range strings.Split(t, "/") {
		switch seg {
		case "", ".":
			continue
		case "..":
			if len(parts) > 0 {
				parts = parts[:len(parts)-1]
			}
		default:
			parts = append(parts, seg)
		}
	}
	if absolute {
		return "/" + strings.Join(parts, "/")
	}
	if len(parts) == 0 {
		// A relative path collapsing to nothing is the CWD, not the root.
		return "."
	}
	return strings.Join(parts, "/")
}

const (
	reasonTildeEscape = "'~' is your home directory and '..' escapes to an unknown parent"
	reasonHome        = "your whole home directory"
	// reasonUnexpanded itself is compared by the chmod branch below.
	reasonUnexpanded = "target holds an unexpanded variable or substitution -- " +
		"if it is empty, this hits /"
)

var unresolvedRe = regexp.MustCompile(`\$\{?\w+|\$\(|` + "`")

// isCritical reports whether an argument is a critical target, a glob over one,
// or an unresolvable expansion.
func isCritical(tok string) (bool, string) {
	if tok == "" || strings.HasPrefix(tok, "-") {
		return false, ""
	}
	if strings.HasPrefix(tok, "~") {
		rest := tok[1:]
		for _, seg := range strings.Split(rest, "/") {
			if seg == ".." {
				return true, reasonTildeEscape
			}
		}
		if rest == "root" || strings.HasPrefix(rest, "root/") {
			norm := normPath("/root" + rest[len("root"):])
			if criticalTargets[norm] || criticalFiles[norm] {
				return true, fmt.Sprintf("target is the critical path %s", norm)
			}
		}
	}
	if unresolvedRe.MatchString(tok) {
		if tok == "$HOME" || tok == "${HOME}" ||
			strings.HasPrefix(tok, "$HOME/") || strings.HasPrefix(tok, "${HOME}/") {
			return true, reasonHome
		}
		return true, reasonUnexpanded
	}
	norm := normPath(tok)
	if criticalTargets[norm] {
		return true, fmt.Sprintf("target is the critical path %s", norm)
	}
	if criticalFiles[norm] {
		return true, fmt.Sprintf("target is the critical system file %s", norm)
	}
	if wholeHomeRe.MatchString(norm) {
		return true, fmt.Sprintf("target is a whole user home directory (%s)", norm)
	}
	if strings.ContainsAny(tok, "*?[") {
		parent := ""
		if i := strings.LastIndex(tok, "/"); i >= 0 {
			parent = tok[:i]
		}
		parentNorm := ""
		if parent != "" {
			parentNorm = normPath(parent)
		}
		if strings.HasPrefix(tok, "/") && (criticalTargets[parentNorm] || parent == "") {
			shown := parentNorm
			if shown == "" {
				shown = "/"
			}
			return true, fmt.Sprintf("glob across the critical path %s", shown)
		}
	}
	return false, ""
}

// flagLetters collects flag letters, normalizing long options and bundles.
func flagLetters(tokens []string) map[string]bool {
	out := map[string]bool{}
	for _, t := range tokens {
		if s, ok := longToShort[t]; ok {
			for _, ch := range strings.TrimLeft(s, "-") {
				out[string(ch)] = true
			}
		} else if strings.HasPrefix(t, "--") {
			out[t] = true
		} else if strings.HasPrefix(t, "-") && len(t) > 1 {
			for _, ch := range t[1:] {
				out[string(ch)] = true
			}
		}
	}
	return out
}

// --- semantic-class regex fragments (RE2 rewrites of the Python fragments) --

// A private key or credential file. PUBLIC keys are excluded: `id_rsa.pub`.
// The (?!\.pub) lookahead is emulated as (?:$|[^.]|\.[^p]|\.p[^u]|\.pu[^b]).
const secretFile = `(?:id_rsa|id_dsa|id_ecdsa|id_ed25519)(?:$|[^.]|\.[^p]|\.p[^u]|\.pu[^b])` +
	`|/etc/(?:shadow|gshadow)(?:$|[^\w.])` +
	`|\.aws/credentials|\.netrc|\.pgpass|\.git-credentials|\.npmrc|\.pypirc` +
	`|\.docker/config\.json|\.kube/config|\.gnupg/[\w.-]{1,40}` +
	`|private[_-]?key|\.pem(?:$|[^\w])|(?:^|[^\w-])\.env(?:$|[^\w.])`

// Sinks that carry bytes OFF the machine and take a BODY (not ssh).
const netSink = `\|\s{0,4}(?:sudo\s+)?(?:curl|wget|nc|ncat|netcat|socat|mail|mailx|sendmail)\b` +
	`|\b(?:curl|wget)\b[^|;]{0,200}(?:--data|--upload-file|--form|\s-d\s|\s-T\s|\s-F\s)`

// scp/rsync/sftp with the secret in the middle and a remote destination.
const copyOut = `\b(?:scp|rsync|sftp)\b[^|;]{0,160}(?:` + secretFile + `)` +
	`[^|;]{0,160}[\w.-]{1,64}@[\w.-]{1,64}:`

// Shell startup files.
const shellRC = `(?:\.bashrc|\.bash_profile|\.bash_login|\.profile|\.zshrc|\.zprofile` +
	`|\.zshenv|\.kshrc|\.cshrc|/etc/profile|/etc/bash\.bashrc)`

type rule struct {
	re     *regexp.Regexp
	reason string
}

func mk(pat, reason string) rule { return rule{regexp.MustCompile(pat), reason} }

// Patterns checked against the WHOLE command (they need to see `|` or `;`).
var wholeDanger = []rule{
	mk(`\b(curl|wget)\b[^|;]*\|\s*(sudo\s+)?(ba|z|k|fi|da)?sh\b`,
		"internet content piped straight into a shell"),
	mk(`\w{0,16}\(\s{0,4}\)\s{0,4}\{[^}]{0,64}\|[^}]{0,64}&\s{0,4}\}\s{0,4};`,
		"fork bomb"),
	mk(`\bmkfs(\.\w+)?\b`, "formats a filesystem"),
	mk(`\bdd\b[^|;]*\bof=/dev/(sd|nvme|hd|vd|mmcblk)`, "raw write straight to a block device"),
	mk(`>\s*/dev/(sd|nvme|hd|vd|mmcblk)`, "redirect onto a block device"),
	mk(`\b(wipefs|blkdiscard|sgdisk)\b[^|;]*/dev/(sd|nvme|hd|vd|mmcblk)`, "wipes a block device"),
	mk(`\bcryptsetup\b[^|;]*\b(luksFormat|luksErase|erase)\b[^|;]*/dev/(sd|nvme|hd|vd|mmcblk)`,
		"reformats or erases a block device"),
	mk(`\bparted\b[^|;]*/dev/(sd|nvme|hd|vd|mmcblk)[^|;]*\b(rm|mklabel)\b`,
		"rewrites a block device partition table"),
	mk(`\b(shutdown|reboot|halt|poweroff|init\s+0|init\s+6)\b`, "shuts the machine down"),
	mk(`\bgit\s+reset\s+--hard\b`, "git reset --hard throws away uncommitted work"),
	mk(`\b(history\s+-c|shred\s+.*\.bash_history)\b`, "erases the shell history"),
	mk(`\bchmod\b[^|;]*\s0{3,4}\s+/\s*$`, "chmod 000 / leaves the system unusable"),
	mk(`\btruncate\s+-s\s*0\s+/etc/(passwd|shadow|fstab|sudoers)\b`,
		"destroys a critical system file"),
	mk(`>\|?\s*/etc/(passwd|shadow|fstab|sudoers)\b`, "destroys a critical system file"),
	mk(`\bln\b[^|;]*-\w*f\w*[^|;]*/etc/(passwd|shadow|fstab|sudoers)\b`,
		"overwrites a critical system file with a symlink"),
	mk(`\binstall\b[^|;]*/etc/(passwd|shadow|fstab|sudoers)\b`,
		"install(1) truncates or replaces the destination file"),
	mk(`\bfind\b[^|]*(?:^|\s)(/|/etc|/usr|/var|/home|/boot|/bin|/sbin|/lib\w*|/root)(?:\s|$)`+
		`[^|]*\|\s*xargs\b[^|]*\b(rm|shred|unlink|srm|rmdir)\b`,
		"search over a critical path piped into delete"),
	mk(`--no-preserve-root`, "explicitly overrides rm's root guard"),
	mk(`\bcrontab\b(?:\s+-\w+)*\s+-\w*r`, "crontab -r deletes the entire crontab without asking"),
	mk(`\b(?:userdel|deluser)\b[^|;]*\s--?(?:r\b|remove-home|remove-all-files)`,
		"deletes a user account together with its home directory and files"),
	mk(`\biptables\b[^|;]*\s-[FX]\b|\bnft\s+flush\s+ruleset\b`,
		"flushes the firewall rules -- can lock you out of a remote machine"),
	mk(`\bchmod\b[^|;]*\s(?:0?[0-7][4-7][0-7]|0?[0-7][0-7][4-7]|[ugoa]*\+r)\s`+
		`[^|;]*(?:id_rsa|id_dsa|id_ecdsa|id_ed25519|private[_-]?key|\.pem)\b`,
		"makes a private key readable by others -- exposed, and ssh will refuse it"),
	mk(`\b(?:apt|apt-get|aptitude|dpkg|yum|dnf|rpm)\b[^|;]*`+
		`\b(?:remove|purge|erase|autoremove)\b[^|;]*`+
		`(?:^|[^\w-])(?:dpkg|apt|apt-get|coreutils|bash|libc6|glibc|systemd|`+
		`util-linux|sudo|linux-image)(?:[^\w-]|$)`,
		"removes an essential package -- the system cannot repair itself"),
	mk(`\bgit\s+reflog\s+expire\b[^|;]*--expire(?:=|\s+)(?:now|all)`+
		`|\bgit\s+gc\b[^|;]*--prune(?:=|\s+)now`,
		"expires the reflog -- git's last route back"),

	// credential exfiltration -- a secret AND an outbound sink.
	mk(`(?:`+secretFile+`)[^;&]{0,240}(?:`+netSink+`)`+
		`|(?:`+netSink+`)[^;&]{0,240}(?:`+secretFile+`)`+
		`|`+copyOut,
		"sends a private key or credential off this machine"),

	// reverse shells and callbacks.
	mk(`\b(?:ba|z|k|da|a)?sh\b[^|;]{0,80}/dev/(?:tcp|udp)/`+
		`|/dev/(?:tcp|udp)/[^\s;]{0,80}0>&1`+
		`|>&\s{0,4}/dev/(?:tcp|udp)/`,
		"reverse shell: a shell's stdin/stdout wired to a remote socket"),
	mk(`\b(?:nc|ncat|netcat|nc\.traditional)\b[^|;]{0,160}`+
		`(?:\s-\w{0,3}[ec]\s|--exec\b|--sh-exec\b|--lua-exec\b)`,
		"netcat -e/--exec: a shell for whoever connects"),
	mk(`\bmkfifo\b[^\n]{0,200}\|[^\n]{0,200}\b(?:nc|ncat|netcat)\b`+
		`|\b(?:nc|ncat|netcat)\b[^\n]{0,200}\|[^\n]{0,200}\bmkfifo\b`,
		"reverse shell over a named pipe (mkfifo + netcat)"),
	mk(`\bsocat\b[^;]{0,200}\b(?:EXEC|SYSTEM):`,
		"socat EXEC:/SYSTEM: runs a program for the remote peer -- a bind or reverse shell"),
	mk(`\b(?:python\d?(?:\.\d+)?|perl|ruby|php|node)\b[^\n]{0,400}\bsocket\b`+
		`[^\n]{0,400}(?:pty\.spawn|dup2|/bin/(?:ba|z|k|da)?sh|\bexec\s*\()`,
		"scripted reverse shell: opens a socket and attaches a shell to it"),

	// privilege escalation.
	mk(`\bchmod\b[^|;]{0,120}\s(?:0?[467][0-7]{3}|[ugoa]*u\+s|\+s(?:\s|$))`,
		"sets the setuid bit -- the file runs as its owner (root) for every user"),
	mk(`\b(?:usermod|gpasswd|adduser|useradd)\b[^|;&]{0,120}`+
		`(?:^|[^\w-])(?:sudo|wheel|admin|root)(?:[^\w-]|$)`,
		"grants root-equivalent group membership"),
	mk(`NOPASSWD`, "grants sudo without a password"),
	mk(`>\|?>?\s{0,4}/etc/sudoers\.d/|\btee\b[^|;]{0,120}/etc/sudoers`, "installs a new sudo rule"),
	mk(`\bsudo\b[^|;&]{0,200}\b(?:find|tar|zip|awk|gawk|mawk|perl|python\d?|ruby`+
		`|node|lua|vim|vi|view|nano|ed|less|more|man|ftp|nmap|git|env|nice`+
		`|tcpdump|rsync|xargs)\b[^|;&]{0,200}`+
		`(?:/bin/(?:ba|z|k|da)?sh|\bsystem\s*\(|\bos\.system|pty\.spawn`+
		`|\bexec\s*\(|:!|!\s{0,2}/bin/|--interactive|checkpoint-action=exec)`,
		"living off the land: sudo runs a tool that then opens a root shell"),

	// persistence.
	mk(`(?:^|[^>])>\|?\s{0,4}\S{0,64}`+shellRC+`(?:$|[^\w.])`,
		"overwrites a shell startup file, dropping everything already in it"),

	// history and log tampering.
	mk(`(?:^|[^>])>\|?\s{0,4}\S{0,64}\.(?:bash|zsh|sh)_history`+
		`|\b(?:rm|shred|truncate)\b[^|;]{0,120}\.(?:bash|zsh|sh)_history`+
		`|\bunset\s+HISTFILE(?:$|[^\w])|\bHISTFILE=(?:/dev/null|\s|$)`+
		`|\bset\s\+o\s+history\b|\bexport\s+HISTSIZE=0\b`,
		"erases or disables the shell history -- hides what was run"),
	mk(`(?:^|[^>])>\|?\s{0,4}/var/log/\S+`+
		`|\btruncate\b[^|;]{0,80}-s\s{0,2}0\s+/var/log/`+
		`|\bjournalctl\b[^|;]{0,80}--vacuum-(?:time|size|files)`,
		"empties the system logs in place"),

	// firewall / MAC controls.
	mk(`\bufw\b[^|;&]{0,60}\b(?:disable|reset)\b|\bsetenforce\s+0\b`+
		`|\bsystemctl\b[^|;&]{0,60}\b(?:stop|disable|mask)\b[^|;&]{0,60}`+
		`\b(?:firewalld|ufw|iptables|nftables|apparmor)\b`+
		`|\biptables\b[^|;&]{0,80}-P\s+(?:INPUT|FORWARD)\s+DROP\b`,
		"turns off the host firewall or its mandatory access control"),

	// storage teardown addressed by NAME.
	mk(`\b(?:lvremove|vgremove|pvremove)\b|\bzpool\s+destroy\b|\bzfs\s+destroy\b`+
		`|\bmdadm\b[^|;]{0,80}--zero-superblock\b`+
		`|\bhdparm\b[^|;]{0,80}--security-erase`,
		"destroys a logical volume, pool or array"),
	mk(`\bumount\b[^|;]{0,40}(?:-\w{0,3}a\s|-\w{0,3}a$|(?:^|\s)/(?:\s|$))`,
		"unmounts the root filesystem (or every mount at once)"),

	// remote code execution beyond curl|sh.
	mk(`\b(?:curl|wget)\b[^|;]{0,200}\|\s{0,4}(?:sudo\s+)?`+
		`(?:python\d?(?:\.\d+)?|perl|ruby|node|php)\b`,
		"internet content piped straight into an interpreter"),
	mk(`(?:\b(?:ba|z|k|da)?sh\b|\bsource\b|(?:^|[^\w.])\.\s)[^|;]{0,40}`+
		`<\(\s{0,4}(?:curl|wget)\b`+
		`|\beval\b[^|;]{0,60}["']?\$\(\s{0,4}(?:curl|wget)\b`,
		"runs remote content through process substitution -- the same as curl | sh"),
	mk(`\bbase64\b[^|;]{0,60}(?:-d|--decode)[^|;]{0,60}`+
		`\|\s{0,4}(?:sudo\s+)?(?:ba|z|k|da)?sh\b`,
		"decodes and runs hidden content"),
}

// git clean needs two flag clusters (f-or-x AND d-or-x); handled apart because
// the Python rule used two lookaheads RE2 cannot express.
var gitCleanF = regexp.MustCompile(`\bgit\s+clean\b[^|;]*-\w*[fx]`)
var gitCleanD = regexp.MustCompile(`\bgit\s+clean\b[^|;]*-\w*[dx]`)

// authorized_keys: a truncating redirect, or a tee WITHOUT an append flag.
var akRedirect = regexp.MustCompile(`(?:^|[^>])>\|?\s*[^\s|;>]*authorized_keys`)
var akTee = regexp.MustCompile(`\btee\b[^|;]*authorized_keys`)
var akTeeAppend = regexp.MustCompile(`\btee\s+-\w*a`)

var wholeCaution = []rule{
	mk(`\brsync\b[^|;]*--delete\b`,
		"rsync --delete removes files at the destination that the source does not have"),
	mk(`\b(awk|cut|sed)\b[^|]*\|\s*xargs\b[^|]*\b(kill|docker\s+rm|rm)\b`,
		"kills or removes by a field parsed out of text -- check that column really is the ID"),
	mk(`\b(?:fuser|pkill|killall|kill)\b(?:\s+-{1,2}\w+)*\s+-?\d+\s*(?:$|[|;&])`,
		"kills a process by a literal pid or port number -- confirm it is the right one"),
	mk(`\b(curl|wget)\b[^|;]*\b(https?://|[a-z0-9-]+\.[a-z]{2,})`, "contacts the network"),
	mk(`\bdocker\s+system\s+prune\b[^|;]*-a|\bdocker\s+system\s+prune\s+-a`,
		"removes every unused docker image, not just the dangling ones"),
	mk(`\bsudo\b`, "runs as root"),
	mk(`\bsetfacl\b[^|;]*-\w*R\w*[^|;]*(?:^|\s)`+
		`(/|/etc|/usr|/var|/home|/boot|/bin|/sbin|/root)(?:\s|$)`,
		"rewrites ACLs recursively over a critical path"),

	// semantic classes, at CAUTION.
	mk(`\b(?:cat|less|more|head|tail|strings|xxd|od|base64)\b`+
		`[^|;]{0,200}(?:`+secretFile+`)`,
		"prints a private key or credential file to the terminal"),
	mk(`/dev/(?:tcp|udp)/`, "opens a raw network socket through bash's /dev/tcp"),
	mk(`\|\s{0,4}(?:sudo\s+)?crontab\s+-\s{0,4}(?:$|[|;&])`,
		"`crontab -` replaces the ENTIRE crontab with whatever it reads"),
	mk(`>>\s{0,4}\S{0,64}`+shellRC+`(?:$|[^\w.])`+
		`|\btee\b[^|;]{0,120}`+shellRC+`(?:$|[^\w.])`+
		`|(?:>\|?>?|\btee\b[^|;]{0,120})\s{0,4}`+
		`/etc/(?:cron\.[a-z]{1,8}/|crontab|rc\.local|systemd/system/|init\.d/)`,
		"installs code that runs itself at every login or boot"),
	mk(`\bchmod\b[^|;]{0,120}\s(?:[0-7]?[0-7]{2}[2367](?:\s|$)|[ugoa]*o\+w)`,
		"makes a file writable by every user on the machine"),
	mk(`\bchmod\b[^|;]{0,120}\s(?:0?2[0-7]{3}(?:\s|$)|[ugoa]*g\+s)`, "sets the setgid bit"),
	mk(`\bmount\b[^|;]{0,80}\bremount\b[^|;]{0,40}(?:^|\s)/(?:\s|$)`,
		"remounts the root filesystem -- running services may start failing"),
}

// ping without a -c count runs forever; two Python lookaheads, handled apart.
var pingRe = regexp.MustCompile(`^\s*(sudo\s+)?ping\b`)
var pingCountRe = regexp.MustCompile(`\s-[a-zA-Z]*c\b|\s-c\d`)

var placeholderRe = regexp.MustCompile(`<[^<>\s][^<>]*>`)

// keystrokeRe matches keyname notation: <Ctrl x>, <Ctrl + x>, <ESC>, <F1>,
// <Enter>. These read like placeholders but are the literal answer to "how do
// I quit vim", so warning "replace this first" on them is the cry-wolf the
// module docstring warns about. A named key is not a blank to fill in.
var keystrokeRe = regexp.MustCompile(
	`(?i)^<(esc(ape)?|ctrl|alt|shift|meta|super|cmd|command|option|tab|enter|` +
		`return|space(bar)?|backspace|del(ete)?|ins(ert)?|home|end|pgup|pgdn|` +
		`page ?(up|down)|up|down|left|right|f[1-9][0-9]?)\b[^<>]*>$`)

// keystrokeOnly reports that every angle-bracket group in the command names a
// key, so nothing in it is a placeholder awaiting substitution. A command that
// mixes both (`vim <file>` after pressing <ESC>) keeps the warning.
func keystrokeOnly(clean string) bool {
	groups := placeholderRe.FindAllString(clean, -1)
	if len(groups) == 0 {
		return false
	}
	for _, g := range groups {
		if !keystrokeRe.MatchString(g) {
			return false
		}
	}
	return true
}

var placeholderHint = regexp.MustCompile(
	`(/path/to/|/path/of/|\byour[-_]|\bmy[-_]|\bfilename\b|\bscript_name\b|` +
		`\bcontainer[-_]id\b|example\.com|username/repo)`)

// findDeletes / findRepermissions / findNarrow key the find(1) branch.
var findDeletes = regexp.MustCompile(`-delete\b|-(?:exec|ok)\w*\s+(sudo\s+)?(rm|shred|truncate)\b`)
var findReperm = regexp.MustCompile(`-(?:exec|ok)\w*\s+(sudo\s+)?(chmod|chown|chgrp)\b`)
var findNarrow = regexp.MustCompile(
	`-i?(?:name|path|regex)\b|-(?:mtime|mmin|atime|amin|ctime|cmin|size|newer)\b`)
var findFilter = regexp.MustCompile(`-i?(?:name|path|regex)\b`)
var substHead = regexp.MustCompile(`\$\(|` + "`")
var devBlock = regexp.MustCompile(`/dev/(sd|nvme|hd|vd|mmcblk)`)
var writeSystemDir = regexp.MustCompile(`(^|\s)(>|>>)\|?\s*/(etc|usr|var|boot|lib|sbin|bin)/`)

// splitSegments splits on shell operators so each clause is judged on its own.
// A lone `|` is a pipe, but `>|` is bash's force-clobber redirect (one token),
// so a `|` immediately after `>` is kept.
func splitSegments(command string) []string {
	var segs []string
	var cur strings.Builder
	flush := func() {
		if s := strings.TrimSpace(cur.String()); s != "" {
			segs = append(segs, s)
		}
		cur.Reset()
	}
	for i := 0; i < len(command); {
		c := command[i]
		switch c {
		case ';', '\n':
			flush()
			i++
		case '&':
			flush()
			if i+1 < len(command) && command[i+1] == '&' {
				i += 2
			} else {
				i++
			}
		case '|':
			if i+1 < len(command) && command[i+1] == '|' {
				flush()
				i += 2
			} else if i > 0 && command[i-1] == '>' {
				cur.WriteByte(c) // >| force-clobber, not a pipe
				i++
			} else {
				flush()
				i++
			}
		default:
			cur.WriteByte(c)
			i++
		}
	}
	flush()
	return segs
}

// Check returns the findings for a command. An empty slice means nothing
// flagged. Every Reason is printed to the user, so each one is a short phrase
// that says what the command does -- with one colour for both levels, the
// wording is the only thing carrying severity.
func Check(command string) []Finding {
	if strings.TrimSpace(command) == "" {
		return nil
	}
	clean := stripControl(command)
	// Placeholders are documentation, not shell syntax: the `>` inside
	// `docker exec -it <container-id> sh` must not read as a redirect.
	scan := placeholderRe.ReplaceAllString(clean, "PLACEHOLDER")

	var findings []Finding
	for _, r := range wholeDanger {
		if r.re.MatchString(scan) {
			findings = append(findings, Finding{LevelDanger, r.reason})
		}
	}
	if gitCleanF.MatchString(scan) && gitCleanD.MatchString(scan) {
		findings = append(findings, Finding{LevelDanger,
			"git clean deletes untracked files with no way back"})
	}
	if akRedirect.MatchString(scan) ||
		(akTee.MatchString(scan) && !akTeeAppend.MatchString(scan)) {
		findings = append(findings, Finding{LevelDanger,
			"overwrites authorized_keys -- can lock you out of ssh"})
	}
	for _, r := range wholeCaution {
		if r.re.MatchString(scan) {
			findings = append(findings, Finding{LevelCaution, r.reason})
		}
	}
	if pingRe.MatchString(scan) && !pingCountRe.MatchString(scan) {
		findings = append(findings, Finding{LevelCaution,
			"ping without -c runs until you interrupt it"})
	}

	// Stateful cd tracking (see the Python comments for each guard).
	cwdIsCritical := false
	cwdAscended := false
	cdSeen := false

	for _, seg := range splitSegments(scan) {
		toks := tokenize(seg)
		if len(toks) == 0 {
			continue
		}

		// Strip no-op wrappers and VAR=value prefixes, then basename the binary.
		for len(toks) > 0 {
			head := toks[0]
			if strings.Contains(head, "=") && !strings.HasPrefix(head, "-") &&
				!strings.HasPrefix(head, "/") && isIdentifier(head[:strings.Index(head, "=")]) {
				toks = toks[1:]
				continue
			}
			base := head[strings.LastIndex(head, "/")+1:]
			if wrappers[base] {
				toks = toks[1:]
				valueOpts := wrapperValueOpts[base]
				for len(toks) > 0 && toks[0] != "--" && strings.HasPrefix(toks[0], "-") {
					opt := toks[0]
					toks = toks[1:]
					if valueOpts[opt] && len(toks) > 0 && !strings.HasPrefix(toks[0], "-") {
						toks = toks[1:]
					}
				}
				if len(toks) > 0 && toks[0] == "--" {
					toks = toks[1:]
				}
				continue
			}
			break
		}
		if len(toks) == 0 {
			continue
		}

		// A command name from substitution cannot be resolved statically.
		if substHead.MatchString(toks[0]) {
			findings = append(findings, Finding{LevelCaution,
				"the command name comes from a substitution -- what will run cannot be checked"})
			continue
		}

		verb := toks[0][strings.LastIndex(toks[0], "/")+1:]

		// `bash -c "<command>"` hides the command inside a string argument.
		if shellRunners[verb] {
			for i := 1; i < len(toks); i++ {
				if toks[i] == "-c" && i+1 < len(toks) {
					findings = append(findings, Check(toks[i+1])...)
					break
				}
			}
		}

		// `eval STRING` is the other run-this-text form.
		if verb == "eval" && len(toks) > 1 {
			findings = append(findings, Check(strings.Join(toks[1:], " "))...)
			continue
		}

		args := toks[1:]
		flags := flagLetters(toks)

		if verb == "rsync" && hasDeleteFlag(args) {
			positional := positionals(args)
			if len(positional) > 0 {
				if crit, why := isCritical(positional[len(positional)-1]); crit {
					findings = append(findings, Finding{LevelDanger,
						"rsync --delete onto a critical path: " + why})
				}
			}
		}

		if verb == "cd" {
			target := firstPositional(args)
			if target != "" {
				crit, _ := isCritical(target)
				cwdIsCritical = crit
				if containsSeg(target, "..") {
					cwdAscended = true
				} else if strings.HasPrefix(target, "/") {
					cwdAscended = false // absolute cd re-anchors
				}
			}
			cdSeen = true
			continue
		}

		switch {
		case destructiveVerbs[verb]:
			hit := false
			for _, a := range args {
				if crit, why := isCritical(a); crit {
					findings = append(findings, Finding{LevelDanger, verb + ": " + why})
					hit = true
					break
				}
			}
			if !hit && cwdIsCritical && anyGlob(args) {
				findings = append(findings, Finding{LevelDanger,
					verb + ": glob inside a critical directory entered by an earlier cd"})
				hit = true
			}
			if !hit && cwdAscended && anyGlob(args) {
				findings = append(findings, Finding{LevelDanger, verb +
					": glob delete in a directory reached with 'cd ..' -- the target is the " +
					"parent of where you started, which cannot be resolved"})
				hit = true
			}
			if !hit && !cdSeen && (flags["r"] || flags["R"]) {
				positional := positionals(args)
				if len(positional) > 0 && allWholeCwd(positional) {
					findings = append(findings, Finding{LevelDanger, verb +
						": recursive delete of the current directory (unknown -- no cd before this) " +
						"with no subdirectory or name filter to narrow it"})
					hit = true
				}
			}
			if !hit {
				for _, a := range args {
					if !strings.HasPrefix(a, "-") &&
						(placeholderRe.FindString(a) == a || placeholderHint.MatchString(a)) {
						findings = append(findings, Finding{LevelDanger, verb +
							": target is a placeholder -- the real path you put there is deleted " +
							"for good"})
						break
					}
				}
			}
		case verb == "find":
			deletes := findDeletes.MatchString(seg)
			reperm := findReperm.MatchString(seg)
			if deletes || reperm {
				label := "find + chmod/chown"
				if deletes {
					label = "find + delete"
				}
				var roots []string
				for _, a := range args {
					if strings.HasPrefix(a, "-") {
						break
					}
					roots = append(roots, a)
				}
				hit := false
				narrowed := findNarrow.MatchString(seg)
				for _, a := range roots {
					if crit, why := isCritical(a); crit {
						lvl := LevelDanger
						if narrowed && normPath(a) != "/" {
							lvl = LevelCaution
						}
						findings = append(findings, Finding{lvl, label + ": " + why})
						hit = true
						break
					}
				}
				if !hit && !cdSeen && deletes {
					rootIsCwd := len(roots) == 0
					if !rootIsCwd {
						rootIsCwd = true
						for _, r := range roots {
							if r != "." && r != "./" {
								rootIsCwd = false
								break
							}
						}
					}
					if rootIsCwd && !findFilter.MatchString(seg) {
						findings = append(findings, Finding{LevelDanger,
							"find + delete: recursive delete under the current directory with " +
								"no name or path filter to narrow it"})
					}
				}
			}
		case moveVerbs[verb]:
			if verb == "mv" && len(args) > 0 {
				if crit, why := isCritical(args[0]); crit {
					findings = append(findings, Finding{LevelDanger, "mv: " + why})
				}
			}
		case permVerbs[verb]:
			positional := positionals(args)
			recursive := flags["r"] || flags["R"]
			for _, a := range rest(positional) {
				crit, why := isCritical(a)
				if crit && !recursive && why == reasonUnexpanded {
					continue
				}
				if crit {
					suffix := ""
					if recursive {
						suffix = " -R"
					}
					findings = append(findings, Finding{LevelDanger, verb + suffix + ": " + why})
					break
				}
			}
		case verb == "ln":
			if flags["f"] && len(args) > 0 {
				if crit, why := isCritical(args[len(args)-1]); crit {
					findings = append(findings, Finding{LevelDanger,
						"ln -f: " + why + " (replaced by the new link)"})
				}
			}
		case verb == "install":
			if len(args) > 0 {
				if crit, why := isCritical(args[len(args)-1]); crit {
					findings = append(findings, Finding{LevelDanger, "install: " + why})
				}
			}
		case verb == "wipefs" || verb == "blkdiscard" || verb == "sgdisk":
			for _, a := range args {
				if devBlock.MatchString(a) {
					findings = append(findings, Finding{LevelDanger, verb + ": wipes a block device"})
					break
				}
			}
		case verb == "tee":
			for _, a := range args {
				if crit, why := isCritical(a); crit {
					findings = append(findings, Finding{LevelDanger,
						"tee: " + why + " (written over by tee)"})
					break
				}
			}
		case verb == "dd":
			for _, a := range args {
				if strings.HasPrefix(a, "of=") {
					if crit, why := isCritical(a[3:]); crit {
						findings = append(findings, Finding{LevelDanger,
							"dd: " + why + " (overwritten by dd)"})
					}
					break
				}
			}
		}

		if writeSystemDir.MatchString(seg) {
			findings = append(findings, Finding{LevelCaution, "writes into a system directory"})
		}
	}

	if (placeholderRe.MatchString(clean) && !keystrokeOnly(clean)) ||
		placeholderHint.MatchString(clean) {
		findings = append(findings, Finding{LevelCaution,
			"contains a placeholder -- replace it before running"})
	}

	return dedup(findings)
}

// --- small helpers ----------------------------------------------------------

func isIdentifier(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') {
			continue
		}
		if i > 0 && r >= '0' && r <= '9' {
			continue
		}
		return false
	}
	return true
}

func hasDeleteFlag(args []string) bool {
	for _, a := range args {
		if a == "--delete" || strings.HasPrefix(a, "--delete") {
			return true
		}
	}
	return false
}

func positionals(args []string) []string {
	var out []string
	for _, a := range args {
		if !strings.HasPrefix(a, "-") {
			out = append(out, a)
		}
	}
	return out
}

func firstPositional(args []string) string {
	for _, a := range args {
		if !strings.HasPrefix(a, "-") {
			return a
		}
	}
	return ""
}

func rest(s []string) []string {
	if len(s) <= 1 {
		return nil
	}
	return s[1:]
}

func containsSeg(path, seg string) bool {
	for _, p := range strings.Split(path, "/") {
		if p == seg {
			return true
		}
	}
	return false
}

func anyGlob(args []string) bool {
	for _, a := range args {
		if !strings.HasPrefix(a, "-") && strings.ContainsAny(a, "*?[") {
			return true
		}
	}
	return false
}

func allWholeCwd(positional []string) bool {
	for _, p := range positional {
		switch p {
		case "*", ".", "./", "./*":
		default:
			return false
		}
	}
	return true
}

func dedup(findings []Finding) []Finding {
	seen := map[Finding]bool{}
	var out []Finding
	for _, f := range findings {
		if !seen[f] {
			seen[f] = true
			out = append(out, f)
		}
	}
	return out
}
